'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { eulerianCircuit } = require('./eulerian.js');

/** Structural validation of a claimed Eulerian circuit. */
function assertValidCircuit(edges, result) {
  assert.notEqual(result, null, 'expected a circuit, got null');
  assert.equal(
    result.length,
    edges.length + 1,
    'circuit must contain |E| + 1 vertices'
  );
  assert.equal(
    result[0],
    result[result.length - 1],
    'circuit must be closed (start equals end)'
  );

  // Multiset comparison of traversed edge pairs against the input edges,
  // so parallel edges are counted individually.
  const canon = ([a, b]) => [a, b].sort().join('|');
  const expected = [...edges.map(canon)].sort();
  const actual = [];
  for (let i = 0; i < result.length - 1; i++) {
    actual.push(canon([result[i], result[i + 1]]));
  }
  actual.sort();
  assert.deepEqual(actual, expected, 'each edge must be used exactly once');
}

test('simple triangle cycle', () => {
  const edges = [
    [0, 1],
    [1, 2],
    [2, 0],
  ];
  assertValidCircuit(edges, eulerianCircuit(edges));
});

test('graph with parallel edges and a self-loop', () => {
  const edges = [
    [0, 1],
    [1, 2],
    [2, 0], // triangle
    [0, 1], // parallel duplicate of first edge
    [1, 1], // self-loop at 1
  ];
  const result = eulerianCircuit(edges);
  assertValidCircuit(edges, result);
  // Self-loop must appear as two consecutive identical vertices somewhere.
  assert.ok(
    result.some((v, i) => i > 0 && v === result[i - 1]),
    'self-loop should show up as a repeated consecutive vertex'
  );
});

test('path graph has no Eulerian circuit', () => {
  const edges = [
    [0, 1],
    [1, 2],
    [2, 3],
  ];
  assert.equal(eulerianCircuit(edges), null);
});

test('classic envelope graph has no circuit (two odd-degree vertices)', () => {
  // Square 1-2-3-4 with both diagonals plus a triangular top flap (apex 5).
  // Degrees: 1->3, 2->3 (odd), others even => Eulerian path exists,
  // but no Eulerian circuit.
  const edges = [
    [1, 2],
    [2, 3],
    [3, 4],
    [4, 1], // square
    [1, 3],
    [2, 4], // the X
    [4, 5],
    [5, 3], // top flap
  ];
  assert.equal(eulerianCircuit(edges), null);
});

test('disconnected edges yield null', () => {
  const edges = [
    [0, 1],
    [1, 0],
    [10, 11],
    [11, 10],
  ];
  assert.equal(eulerianCircuit(edges), null);
});

test('single self-loop', () => {
  const edges = [['a', 'a']];
  assertValidCircuit(edges, eulerianCircuit(edges));
});

test('empty edge list gives the trivial circuit', () => {
  assert.deepEqual(eulerianCircuit([]), []);
});

test('larger mixed multigraph', () => {
  const edges = [
    ['u', 'v'],
    ['v', 'w'],
    ['w', 'u'],
    ['u', 'x'],
    ['x', 'y'],
    ['y', 'u'],
    ['w', 'x'],
    ['w', 'x'],
  ];
  assertValidCircuit(edges, eulerianCircuit(edges));
});

