'use strict';

/**
 * Hierholzer's algorithm for an undirected multigraph.
 *
 * @param {Array<[any, any]>} edges - edges as [u, v] pairs (self-loops and
 *   parallel edges allowed).
 * @returns {Array|null} a vertex sequence of length edges.length + 1 using
 *   every edge exactly once, with first vertex equal to the last, or null if
 *   no Eulerian circuit exists (odd-degree vertex or edge-disconnected graph).
 */
function eulerianCircuit(edges) {
  const m = edges.length;
  if (m === 0) return [];

  // Build adjacency lists of {other, id} so parallel edges stay distinct.
  const adj = new Map();
  const degree = new Map();
  for (let id = 0; id < m; id++) {
    const [u, v] = edges[id];
    for (const w of [u, v]) {
      if (!adj.has(w)) adj.set(w, []);
      degree.set(w, (degree.get(w) || 0) + 1);
    }
    adj.get(u).push({ other: v, id });
    adj.get(v).push({ other: u, id });
  }

  // Necessary condition 1: every vertex has even degree.
  for (const d of degree.values()) {
    if (d % 2 !== 0) return null;
  }

  // Necessary condition 2: all vertices incident to an edge are connected
  // (isolated vertices elsewhere are irrelevant).
  const start = edges[0][0];
  const seen = new Set([start]);
  const queue = [start];
  while (queue.length > 0) {
    const v = queue.pop();
    for (const e of adj.get(v)) {
      if (!seen.has(e.other)) {
        seen.add(e.other);
        queue.push(e.other);
      }
    }
  }
  if (seen.size !== degree.size) return null;

  // Iterative Hierholzer: walk greedily, splice closed loops into the circuit.
  const used = new Array(m).fill(false);
  const stack = [start];
  const circuit = [];
  while (stack.length > 0) {
    const v = stack[stack.length - 1];
    const list = adj.get(v);
    while (list.length > 0 && used[list[list.length - 1].id]) list.pop();
    if (list.length === 0) {
      circuit.push(stack.pop());
    } else {
      const e = list.pop();
      used[e.id] = true;
      stack.push(e.other);
    }
  }

  return circuit.length === m + 1 ? circuit : null;
}

module.exports = { eulerianCircuit };

